1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	
3	// Flat-literal count — raw bytes, comments included, no regex. A value wrapped
4	// across a line break is invisible here (as it is to a grep/sed rename too), so a
5	// guarded value must stay on one line wherever it appears.
6	function countOccurrences(text, value) {
7	  let n = 0;
8	  let pos = 0;
9	  while ((pos = text.indexOf(value, pos)) !== -1) {
10	    n += 1;
11	    pos += value.length;
12	  }
13	  return n;
14	}
15	
16	// Module technologies whose files can `import` a shared definition from one
17	// another (the JS/TS family). A shared-constant only earns its keep for a value
18	// copied across files that CAN'T share an import — JSON manifests, a YAML
19	// workflow + a JS module, prod code + a config file. When every watched file is
20	// one of these, the copy is redundant: export the value once and import it.
21	const IMPORTABLE_EXTENSIONS = new Set([
22	  'js', 'mjs', 'cjs', 'jsx', 'ts', 'tsx', 'mts', 'cts',
23	]);
24	
25	function fileExtension(path) {
26	  const base = path.slice(path.lastIndexOf('/') + 1);
27	  const dot = base.lastIndexOf('.');
28	  return dot > 0 ? base.slice(dot + 1).toLowerCase() : '';
29	}
30	
31	// Data-driven drift guard for a value that must be copied across files that can't
32	// share an import (a label spanning a YAML workflow guard and a JS module; a repo
33	// slug in prod code and its test). The cases are declared per-repo in
34	// .claudinite-settings.json under "sharedConstants"; an empty/absent list is a no-op.
35	// Each entry is { what, value, counts } — value is the literal, counts maps a
36	// repo-relative path to the exact number of times it must appear, and what names
37	// the places and why the split is forced (so the guard self-documents). A count
38	// mismatch means a rename touched some copies but not all.
39	//
40	// A value that must stay in sync but *changes over time* (a version string bumped
41	// each release) sets "regex": true and gives a pattern for value. Then value is
42	// matched as a regular expression, counts still bound the matches per file, and
43	// every matched substring across all the declared files must be byte-identical —
44	// so the guard catches drift without pinning (and re-pinning) the current value.
45	//
46	// An entry whose watched files are all the same import-capable technology (all
47	// JS/TS) is a misuse, not drift: those files CAN share an import, so the value
48	// should live in one module and be imported — not copied and byte-counted. The
49	// guard flags such an entry so the redundancy is fixed at the source.
50	const rule = {
51	  id: 'shared-constants',
52	  severity: 'blocking',
53	  description: 'A value copied across files that can\'t share an import must appear the declared number of times in each (and, in regex mode, be identical everywhere)',
54	  doc: 'packs/basics/RULES.md',
55	  why: 'a value duplicated across files that can\'t share an import drifts silently when a rename or bump lands in some but not all',
56	
57	  run(ctx) {
58	    const out = [];
59	    const cases = ctx.config.sharedConstants ?? [];
60	
61	    cases.forEach((entry, i) => {
62	      const label = entry && typeof entry.value === 'string' && entry.value ? `"${entry.value}"` : `entry #${i + 1}`;
63	
64	      const wellFormed =
65	        entry &&
66	        typeof entry.value === 'string' && entry.value.length > 0 &&
67	        typeof entry.what === 'string' && entry.what.trim().length > 0 &&
68	        entry.counts && typeof entry.counts === 'object' && !Array.isArray(entry.counts) &&
69	        Object.keys(entry.counts).length > 0;
70	
71	      if (!wellFormed) {
72	        out.push(finding(rule, {
73	          file: '.claudinite-settings.json',
74	          what: `malformed sharedConstants ${label}: needs a non-empty "value", a "what" naming the places and why the split is forced, and a non-empty "counts" map`,
75	          fix: 'shape each entry as { "what": "...", "value": "...", "counts": { "repo/relative/path": N } }',
76	        }));
77	        return;
78	      }
79	
80	      // Redundancy guard: a shared-constant is for a value copied across files
81	      // that CAN'T share an import. If every watched file is the same
82	      // import-capable technology (all JS/TS), they can — so the entry is the
83	      // wrong tool; the value should be exported once and imported.
84	      const paths = Object.keys(entry.counts);
85	      if (paths.length > 1 && paths.every((p) => IMPORTABLE_EXTENSIONS.has(fileExtension(p)))) {
86	        out.push(finding(rule, {
87	          file: '.claudinite-settings.json',
88	          what: `sharedConstants ${label} watches only same-technology files that can share an import (${paths.join(', ')}) — a shared-constant is for a value copied across files that CAN'T`,
89	          fix: `export ${label} from one module and import it into the other(s), then drop this entry (${entry.what})`,
90	        }));
91	        return;
92	      }
93	
94	      const isRegex = entry.regex === true;
95	      let regex = null;
96	      if (isRegex) {
97	        try {
98	          regex = new RegExp(entry.value, 'g');
99	        } catch (e) {
100	          out.push(finding(rule, {
101	            file: '.claudinite-settings.json',
102	            what: `sharedConstants ${label} sets "regex": true but "value" is not a valid regular expression: ${e.message}`,
103	            fix: 'fix the pattern, or drop "regex": true to match the value as a flat literal',
104	          }));
105	          return;
106	        }
107	      }
108	
109	      const matched = []; // { rel, value } across files — for the regex-mode equality check
110	      for (const [rel, expected] of Object.entries(entry.counts)) {
111	        if (!Number.isInteger(expected) || expected < 0) {
112	          out.push(finding(rule, {
113	            file: '.claudinite-settings.json',
114	            what: `sharedConstants ${label} gives a non-integer count for ${rel}`,
115	            fix: `set "counts"["${rel}"] to the number of times ${label} must appear in that file`,
116	          }));
117	          continue;
118	        }
119	        const text = ctx.read(rel);
120	        if (text === null) {
121	          out.push(finding(rule, {
122	            file: '.claudinite-settings.json',
123	            what: `sharedConstants ${label} watches ${rel}, but that file does not exist`,
124	            fix: `the value's home moved or was removed — update the entry's "counts" (${entry.what})`,
125	          }));
126	          continue;
127	        }
128	        let actual;
129	        if (isRegex) {
130	          const hits = text.match(regex) || [];
131	          actual = hits.length;
132	          for (const h of hits) matched.push({ rel, value: h });
133	        } else {
134	          actual = countOccurrences(text, entry.value);
135	        }
136	        if (actual !== expected) {
137	          out.push(finding(rule, {
138	            file: rel,
139	            what: `expected ${expected} occurrence(s) of ${label} but found ${actual}`,
140	            fix: `a rename left this file out of sync — fix the value here, or adjust the entry's count if the change is intended (${entry.what})`,
141	          }));
142	        }
143	      }
144	
145	      // Regex mode: the matched substrings must agree across every declared file.
146	      if (isRegex && matched.length > 1) {
147	        const distinct = [...new Set(matched.map((m) => m.value))];
148	        if (distinct.length > 1) {
149	          const detail = distinct
